exercises.solutionCode:
func can_open_gate(switches):
    if switches.size() == 0:
        return false
    for switch in switches:
        if not switch["ready"] or not switch["activated"]:
            return false
    return true

if can_open_gate(switches):
    print("Gate: Open")
else:
    print("Gate: Closed")
